SELECT t.mkt01_target_company_id AS target_company_id
     , CAST(NULL AS NUMERIC)     AS manager_id
     , t.mkt01_target_company_nm AS target_company_name
     , CAST(NULL AS VARCHAR)     AS manager_name
     , CAST(NULL AS VARCHAR)     AS manager_org_name
  FROM ( SELECT mkt01_target_company_id, mkt01_target_company_nm

       ) t
 ORDER BY t.mkt01_target_company_nm collate "ko_KR.utf8" asc
 LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*)
  FROM ( SELECT mkt01_target_company_id

       ) t

